sys_script.script:
(function executeRule(current, previous) {
    var sourceStation = current.getValue('source_station');
    var destStation = current.getValue('destination_station');

    if (!sourceStation || !destStation) {
        return;
    }

    // Validate source != destination
    if (sourceStation == destStation) {
        gs.addErrorMessage('Source and Destination stations cannot be the same.');
        current.setAbortAction(true);
        return;
    }

    // Get station names for route code generation
    var srcGr = new GlideRecord('x_1877508_metro_0_metro_stations');
    if (srcGr.get(sourceStation)) {
        var srcName = srcGr.getValue('station_name') || '';
    }

    var destGr = new GlideRecord('x_1877508_metro_0_metro_stations');
    if (destGr.get(destStation)) {
        var dstName = destGr.getValue('station_name') || '';
    }

    // Generate route code: First 3 chars of each
    var srcCode = srcName.substring(0, 3);
    var dstCode = dstName.substring(0, 3);
    // Capitalize first letter of each
    srcCode = srcCode.charAt(0).toUpperCase() + srcCode.substring(1).toLowerCase();
    dstCode = dstCode.charAt(0).toUpperCase() + dstCode.substring(1).toLowerCase();

    current.setValue('route_code', srcCode + dstCode);

    // Duplicate check
    var dupGr = new GlideRecord('x_1877508_metro_0_metro_routes');
    dupGr.addQuery('source_station', sourceStation);
    dupGr.addQuery('destination_station', destStation);
    dupGr.addQuery('sys_id', '!=', current.getUniqueValue());
    dupGr.query();

    if (dupGr.hasNext()) {
        gs.addErrorMessage('This route already exists.');
        current.setAbortAction(true);
        return;
    }
})(current, previous);
